package history

import (
	"isogloss/engine/lex"
	"isogloss/engine/phon"
)

// Replay rebuilds variety v by applying its history to the proto-language
// with a fresh Applier. Relaxation entries are regenerated by Apply itself
// and skipped. visit, if non-nil, sees every step (before and after).
// Replay is exact: the result has v's key, forms and paradigms (tested).
func Replay(reg *Registry, proto, v *lex.Variety, visit func(e lex.Entry, before, after *lex.Variety)) *lex.Variety {
	ap := NewApplier(reg)
	cur := proto
	for _, e := range v.Adopted() {
		if e.Kind == lex.EntryRelax {
			continue
		}
		next := ap.Apply(cur, e)
		if visit != nil {
			visit(e, cur, next)
		}
		cur = next
	}
	return cur
}

// CellStep is one change to a paradigm cell.
type CellStep struct {
	Tick          int32
	Innov         uint32
	Label         string
	Before, After phon.Word
}

// TraceCell follows one cell of a tracked lexeme's paradigm through v's
// history: sound changes, grammaticalization (a clitic attaching, a clitic
// becoming an affix), analogy and replacement. It returns the proto form
// and the steps that changed the cell.
func TraceCell(reg *Registry, proto, v *lex.Variety, c lex.ConceptID, cell int) (phon.Word, []CellStep, bool) {
	i := lex.TrackedIndex(c)
	if i < 0 || proto.M.Para[i] == nil || cell < 0 || cell >= len(proto.M.Para[i].Forms) {
		return phon.Word{}, nil, false
	}
	start := proto.M.Para[i].Forms[cell]
	var steps []CellStep
	Replay(reg, proto, v, func(e lex.Entry, before, after *lex.Variety) {
		a, b := before.M.Para[i].Forms[cell], after.M.Para[i].Forms[cell]
		if a.Equal(b) && len(a.Bounds) == len(b.Bounds) && sameBounds(a, b) {
			return
		}
		in := reg.Get(e.Innov)
		label := in.Label()
		switch in.Kind {
		case Sound:
			label = in.Template
		case Lexical:
			label = "replaced: " + in.Lex.How
		case Morph:
			label = "analogy (levelled to the regular pattern)"
		case Gram:
			label = in.Gram.Label()
		}
		steps = append(steps, CellStep{e.Tick, in.ID, label, a, b})
	})
	return start, steps, true
}

func sameBounds(a, b phon.Word) bool {
	for k := range a.Bounds {
		if a.Bounds[k] != b.Bounds[k] {
			return false
		}
	}
	return true
}

